'use client';

import { useFrame, useThree } from '@react-three/fiber';
import { useRef, type ReactNode, type RefObject } from 'react';
import * as THREE from 'three';
import type { DeploymentProgress } from './types';
import type { DroneAssemblyHandle } from './DroneAssembly';

type SceneControllerProps = {
  children: ReactNode;
  progress: DeploymentProgress;
  assemblyRef: RefObject<DroneAssemblyHandle | null>;
  desktop: boolean;
  sceneScale: number;
};

export function SceneController({ children, progress, assemblyRef, desktop, sceneScale }: SceneControllerProps) {
  const rootRef = useRef<THREE.Group>(null);
  const { pointer } = useThree();

  useFrame(() => {
    const root = rootRef.current;
    const assembly = assemblyRef.current;
    if (!root || !assembly) return;
    const deployment = Math.max(0, Math.min(1, progress.value));
    const awaken = THREE.MathUtils.smoothstep(deployment, 0.12, 0.32);
    const unfold = THREE.MathUtils.smoothstep(deployment, 0.26, 0.62);
    const explode = THREE.MathUtils.smoothstep(deployment, 0.55, 0.9);

    root.scale.setScalar(sceneScale);
    root.position.y = THREE.MathUtils.lerp(-0.08, 0.08, awaken);
    if (desktop) {
      root.rotation.y = THREE.MathUtils.lerp(root.rotation.y, pointer.x * 0.11, 0.06);
      root.rotation.x = THREE.MathUtils.lerp(root.rotation.x, -pointer.y * 0.06, 0.06);
    } else {
      root.rotation.y = THREE.MathUtils.lerp(root.rotation.y, 0, 0.08);
      root.rotation.x = THREE.MathUtils.lerp(root.rotation.x, 0, 0.08);
    }

    assembly.arms.forEach((arm, index) => {
      if (!arm) return;
      const foldedRotation = index % 2 === 0 ? 0.48 : -0.48;
      arm.rotation.z = THREE.MathUtils.lerp(foldedRotation, 0, unfold);
      arm.position.y = THREE.MathUtils.lerp(0.02, index > 1 ? -0.08 : 0.08, explode);
    });
    if (assembly.body) assembly.body.position.y = THREE.MathUtils.lerp(0, 0.12, awaken);
    if (assembly.controller) assembly.controller.position.y = THREE.MathUtils.lerp(0.28, 0.62, explode);
    if (assembly.electronics) assembly.electronics.position.y = THREE.MathUtils.lerp(-0.34, -0.72, explode);
    if (assembly.sensor) assembly.sensor.position.x = THREE.MathUtils.lerp(0.54, 0.9, explode);
    if (assembly.payload) assembly.payload.position.y = THREE.MathUtils.lerp(-0.62, -1.1, explode);

    const startup = Math.sin(THREE.MathUtils.smoothstep(deployment, 0.78, 0.98) * Math.PI);
    assembly.rotors.forEach((rotor, index) => {
      if (!rotor) return;
      rotor.rotation.y = startup * (index % 2 === 0 ? 0.06 : -0.06);
    });
  });

  return <group ref={rootRef}>{children}</group>;
}
