'use client';

import { forwardRef, useImperativeHandle, useMemo, useRef, type Ref } from 'react';
import * as THREE from 'three';
import type { DronePartId } from './types';

export type DroneAssemblyHandle = {
  root: THREE.Group | null;
  body: THREE.Group | null;
  arms: Array<THREE.Group | null>;
  rotors: Array<THREE.Group | null>;
  controller: THREE.Group | null;
  electronics: THREE.Group | null;
  sensor: THREE.Group | null;
  payload: THREE.Group | null;
};

type DroneAssemblyProps = {
  activePart: DronePartId | null;
};

const ARM_BASIS: readonly [number, number, number][] = [
  [-0.42, 0.02, 0],
  [0.42, 0.02, 0],
  [-0.42, -0.02, 0],
  [0.42, -0.02, 0],
];

const ARM_ROTATION = [0.48, -0.48, -0.48, 0.48];

export const DroneAssembly = forwardRef(function DroneAssembly(
  { activePart }: DroneAssemblyProps,
  ref: Ref<DroneAssemblyHandle>,
) {
  const root = useRef<THREE.Group>(null);
  const body = useRef<THREE.Group>(null);
  const controller = useRef<THREE.Group>(null);
  const electronics = useRef<THREE.Group>(null);
  const sensor = useRef<THREE.Group>(null);
  const payload = useRef<THREE.Group>(null);
  const armRefs = useMemo(() => ARM_BASIS.map(() => ({ current: null } as { current: THREE.Group | null })), []);
  const rotorRefs = useMemo(() => ARM_BASIS.map(() => ({ current: null } as { current: THREE.Group | null })), []);

  useImperativeHandle(ref, () => ({
    root: root.current,
    body: body.current,
    arms: armRefs.map((entry) => entry.current),
    rotors: rotorRefs.map((entry) => entry.current),
    controller: controller.current,
    electronics: electronics.current,
    sensor: sensor.current,
    payload: payload.current,
  }));

  const graphite = '#282b30';
  const edge = '#646a72';
  const violet = '#8b5cf6';
  const cyan = '#06b6d4';

  return (
    <group ref={root} scale={1.28}>
      <group ref={body}>
        <mesh castShadow receiveShadow>
          <octahedronGeometry args={[0.72, 1]} />
          <meshStandardMaterial color={graphite} roughness={0.72} metalness={0.3} />
        </mesh>
        <mesh scale={[0.86, 0.56, 0.86]}>
          <octahedronGeometry args={[0.72, 1]} />
          <meshBasicMaterial color={edge} wireframe transparent opacity={0.34} />
        </mesh>
        <mesh position={[0, -0.12, 0.34]} rotation={[Math.PI / 2, 0, 0]}>
          <torusGeometry args={[0.19, 0.025, 6, 16]} />
          <meshBasicMaterial color={violet} transparent opacity={activePart === 'airframe' ? 0.95 : 0.5} />
        </mesh>
      </group>

      {ARM_BASIS.map((position, index) => (
        <group
          key={`arm-${index}`}
          ref={(node) => { armRefs[index] = { current: node }; }}
          position={position}
          rotation={[0, 0, ARM_ROTATION[index]!]}
        >
          <mesh position={[index % 2 === 0 ? -0.44 : 0.44, 0, 0]} castShadow>
            <boxGeometry args={[0.9, 0.11, 0.12]} />
            <meshStandardMaterial color={graphite} roughness={0.68} metalness={0.38} />
          </mesh>
          <mesh position={[index % 2 === 0 ? -0.44 : 0.44, 0, 0.07]}>
            <boxGeometry args={[0.88, 0.018, 0.018]} />
            <meshBasicMaterial color={edge} transparent opacity={0.62} />
          </mesh>
          <group
            ref={(node) => { rotorRefs[index] = { current: node }; }}
            position={[index % 2 === 0 ? -0.9 : 0.9, 0.03, 0]}
          >
            <mesh>
              <cylinderGeometry args={[0.15, 0.15, 0.12, 8]} />
              <meshStandardMaterial color={graphite} roughness={0.6} metalness={0.4} />
            </mesh>
            <mesh rotation={[Math.PI / 2, 0, 0]}>
              <torusGeometry args={[0.2, 0.012, 6, 18]} />
              <meshBasicMaterial color={activePart === 'rotor' ? '#ffb829' : cyan} transparent opacity={0.72} />
            </mesh>
          </group>
        </group>
      ))}

      <group ref={electronics} position={[0, -0.34, 0]}>
        <mesh>
          <boxGeometry args={[0.44, 0.08, 0.32]} />
          <meshStandardMaterial color="#1a1c1f" roughness={0.75} metalness={0.24} />
        </mesh>
        <mesh position={[0, 0.06, 0]}>
          <boxGeometry args={[0.3, 0.015, 0.18]} />
          <meshBasicMaterial color={cyan} transparent opacity={activePart === 'electronics' ? 0.85 : 0.34} />
        </mesh>
      </group>

      <group ref={controller} position={[0, 0.28, 0]}>
        <mesh>
          <boxGeometry args={[0.24, 0.1, 0.22]} />
          <meshStandardMaterial color="#34383e" roughness={0.6} metalness={0.35} />
        </mesh>
        <mesh position={[0, 0.06, 0]}>
          <sphereGeometry args={[0.055, 12, 8]} />
          <meshBasicMaterial color={violet} transparent opacity={activePart === 'flight-controller' ? 1 : 0.72} />
        </mesh>
      </group>

      <group ref={sensor} position={[0.54, 0.12, 0.08]}>
        <mesh>
          <cylinderGeometry args={[0.12, 0.12, 0.18, 8]} />
          <meshStandardMaterial color="#353a40" roughness={0.68} metalness={0.3} />
        </mesh>
        <mesh position={[0, 0, 0.11]} rotation={[Math.PI / 2, 0, 0]}>
          <circleGeometry args={[0.065, 16]} />
          <meshBasicMaterial color={activePart === 'sensor' ? '#ffb829' : cyan} transparent opacity={0.82} />
        </mesh>
      </group>

      <group ref={payload} position={[0, -0.62, 0]}>
        <mesh>
          <boxGeometry args={[0.38, 0.22, 0.3]} />
          <meshStandardMaterial color="#24272b" roughness={0.72} metalness={0.32} />
        </mesh>
        <mesh position={[0, -0.15, 0]} rotation={[Math.PI / 2, 0, 0]}>
          <torusGeometry args={[0.13, 0.018, 8, 16]} />
          <meshBasicMaterial color={activePart === 'payload' ? '#ffb829' : violet} transparent opacity={0.76} />
        </mesh>
      </group>

      <mesh position={[-0.52, -0.1, 0.14]}>
        <octahedronGeometry args={[0.1, 0]} />
        <meshBasicMaterial color={activePart === 'navigation' ? '#ffb829' : cyan} transparent opacity={0.76} />
      </mesh>
    </group>
  );
});
