'use client';

import { useFrame } from '@react-three/fiber';
import { useLayoutEffect, useMemo, useRef } from 'react';
import * as THREE from 'three';
import type { DeploymentProgress } from './types';

type ParticleQuality = 'desktop' | 'tablet' | 'mobile';

const PARTICLE_COUNTS: Record<ParticleQuality, number> = {
  desktop: 1400,
  tablet: 820,
  mobile: 320,
};

const COLOR_HEX = ['#e5e2e1', '#8b5cf6', '#06b6d4', '#c4c7c7', '#8b5cf6'];

type ParticlePositions = {
  start: Float32Array;
  target: Float32Array;
  exploded: Float32Array;
  scale: Float32Array;
};

function buildPositions(count: number): ParticlePositions {
  const start = new Float32Array(count * 3);
  const target = new Float32Array(count * 3);
  const exploded = new Float32Array(count * 3);
  const scale = new Float32Array(count);

  for (let index = 0; index < count; index += 1) {
    const seed = index * 12.9898;
    const angle = seed % (Math.PI * 2);
    const radius = 0.82 + ((index * 37) % 100) / 100 * 1.05;
    const i3 = index * 3;
    const x = Math.cos(angle) * radius * 1.25;
    const y = Math.sin(angle * 1.31) * radius * 0.72;
    const z = Math.sin(angle * 0.77) * radius * 0.5;
    start[i3] = x * 1.65;
    start[i3 + 1] = y * 1.1 + 0.18;
    start[i3 + 2] = z * 1.2;
    target[i3] = x * 0.8;
    target[i3 + 1] = y * 0.72;
    target[i3 + 2] = z * 0.65;
    exploded[i3] = x * (1.1 + (index % 7) * 0.045);
    exploded[i3 + 1] = y * (1.05 + (index % 5) * 0.07) + (index % 3 === 0 ? 0.22 : -0.08);
    exploded[i3 + 2] = z * (1.18 + (index % 4) * 0.08);
    scale[index] = 0.018 + (index % 5) * 0.004;
  }

  return { start, target, exploded, scale };
}

export function getParticleCount(quality: ParticleQuality) {
  return PARTICLE_COUNTS[quality];
}

export function MeshParticleField({ progress, quality }: { progress: DeploymentProgress; quality: ParticleQuality }) {
  const meshRef = useRef<THREE.InstancedMesh>(null);
  const materialRef = useRef<THREE.MeshBasicMaterial>(null);
  const dummy = useMemo(() => new THREE.Object3D(), []);
  const positions = useMemo(() => buildPositions(PARTICLE_COUNTS[quality]), [quality]);
  const previousProgress = useRef(-1);

  useLayoutEffect(() => {
    const mesh = meshRef.current;
    if (!mesh) return;
    const color = new THREE.Color();
    for (let index = 0; index < mesh.count; index += 1) {
      const i3 = index * 3;
      dummy.position.set(positions.start[i3]!, positions.start[i3 + 1]!, positions.start[i3 + 2]!);
      dummy.scale.setScalar(positions.scale[index]!);
      dummy.updateMatrix();
      mesh.setMatrixAt(index, dummy.matrix);
      color.set(COLOR_HEX[index % COLOR_HEX.length]!);
      mesh.setColorAt(index, color);
    }
    mesh.instanceMatrix.needsUpdate = true;
    if (mesh.instanceColor) mesh.instanceColor.needsUpdate = true;
    previousProgress.current = -1;
  }, [dummy, positions]);

  useFrame(() => {
    const mesh = meshRef.current;
    if (!mesh) return;
    const nextProgress = Math.max(0, Math.min(1, progress.value));
    if (Math.abs(nextProgress - previousProgress.current) < 0.001) return;
    previousProgress.current = nextProgress;

    const awaken = THREE.MathUtils.smoothstep(nextProgress, 0.12, 0.32);
    const exploded = THREE.MathUtils.smoothstep(nextProgress, 0.54, 0.88);
    for (let index = 0; index < mesh.count; index += 1) {
      const i3 = index * 3;
      const cloudX = THREE.MathUtils.lerp(positions.start[i3]!, positions.target[i3]!, awaken);
      const cloudY = THREE.MathUtils.lerp(positions.start[i3 + 1]!, positions.target[i3 + 1]!, awaken);
      const cloudZ = THREE.MathUtils.lerp(positions.start[i3 + 2]!, positions.target[i3 + 2]!, awaken);
      dummy.position.set(
        THREE.MathUtils.lerp(cloudX, positions.exploded[i3]!, exploded),
        THREE.MathUtils.lerp(cloudY, positions.exploded[i3 + 1]!, exploded),
        THREE.MathUtils.lerp(cloudZ, positions.exploded[i3 + 2]!, exploded),
      );
      dummy.scale.setScalar(positions.scale[index]! * (1 + awaken * 0.25));
      dummy.updateMatrix();
      mesh.setMatrixAt(index, dummy.matrix);
    }
    mesh.instanceMatrix.needsUpdate = true;
    if (materialRef.current) materialRef.current.opacity = 0.12 + awaken * 0.38;
  });

  return (
    <instancedMesh ref={meshRef} args={[undefined, undefined, PARTICLE_COUNTS[quality]]} frustumCulled={false}>
      <tetrahedronGeometry args={[1, 0]} />
      <meshBasicMaterial ref={materialRef} transparent opacity={0.12} depthWrite={false} vertexColors />
    </instancedMesh>
  );
}

export type { ParticleQuality };
