'use client';

import { useFrame, type ThreeEvent } from '@react-three/fiber';
import { useMemo, useRef } from 'react';
import * as THREE from 'three';
import { DRONE_PARTS, type DeploymentProgress, type DronePartId } from './types';

const HOTSPOT_POSITIONS: Record<DronePartId, { base: [number, number, number]; exploded: [number, number, number] }> = {
  airframe: { base: [0, -0.42, 0.5], exploded: [-0.4, -0.28, 0.48] },
  rotor: { base: [-1.12, 0.1, 0], exploded: [-1.35, 0.42, 0.08] },
  electronics: { base: [0, -0.68, 0.2], exploded: [-0.12, -0.92, 0.18] },
  'flight-controller': { base: [0, 0.5, 0.2], exploded: [0, 0.78, 0.2] },
  sensor: { base: [0.55, 0.25, 0.16], exploded: [0.92, 0.32, 0.22] },
  payload: { base: [0, -0.88, 0.2], exploded: [0.18, -1.18, 0.24] },
  navigation: { base: [-0.62, -0.22, 0.2], exploded: [-0.86, -0.38, 0.26] },
};

export function DroneHotspots({ progress, activePart, onSelect }: {
  progress: DeploymentProgress;
  activePart: DronePartId | null;
  onSelect: (part: DronePartId) => void;
}) {
  const refs = useMemo(() => DRONE_PARTS.map(() => ({ current: null } as { current: THREE.Group | null })), []);
  const previousProgress = useRef(-1);

  useFrame(() => {
    const nextProgress = Math.max(0, Math.min(1, progress.value));
    if (Math.abs(nextProgress - previousProgress.current) < 0.001) return;
    previousProgress.current = nextProgress;
    const explode = THREE.MathUtils.smoothstep(nextProgress, 0.54, 0.9);
    refs.forEach((entry, index) => {
      const group = entry.current;
      if (!group) return;
      const part = DRONE_PARTS[index]!;
      const position = HOTSPOT_POSITIONS[part.id];
      group.position.set(
        THREE.MathUtils.lerp(position.base[0], position.exploded[0], explode),
        THREE.MathUtils.lerp(position.base[1], position.exploded[1], explode),
        THREE.MathUtils.lerp(position.base[2], position.exploded[2], explode),
      );
      group.scale.setScalar(0.72 + explode * 0.24);
    });
  });

  const handlePointer = (event: ThreeEvent<PointerEvent>, id: DronePartId) => {
    event.stopPropagation();
    onSelect(id);
  };

  return (
    <>
      {DRONE_PARTS.map((part, index) => (
        <group
          key={part.id}
          ref={(node) => { refs[index] = { current: node }; }}
          position={HOTSPOT_POSITIONS[part.id].base}
          onPointerOver={(event) => handlePointer(event, part.id)}
          onPointerDown={(event) => handlePointer(event, part.id)}
        >
          <mesh scale={activePart === part.id ? 1.35 : 1}>
            <ringGeometry args={[0.055, 0.07, 12]} />
            <meshBasicMaterial
              color={activePart === part.id ? '#ffb829' : '#06b6d4'}
              transparent
              opacity={activePart === part.id ? 0.92 : 0.42}
              depthWrite={false}
            />
          </mesh>
          <mesh>
            <sphereGeometry args={[0.16, 8, 8]} />
            <meshBasicMaterial transparent opacity={0} depthWrite={false} />
          </mesh>
        </group>
      ))}
    </>
  );
}
