'use client';

import { Canvas } from '@react-three/fiber';
import { useEffect, useRef, useState, type ComponentProps, type ReactNode } from 'react';
import { DroneAssembly, type DroneAssemblyHandle } from './DroneAssembly';
import { DroneHotspots } from './DroneHotspots';
import { MeshParticleField, type ParticleQuality } from './MeshParticleField';
import { ParticleIntelligenceCore } from './ParticleIntelligenceCore';
import { SceneController } from './SceneController';
import type { DeploymentProgress, DronePartId } from './types';

type DroneExperienceProps = {
  progress: DeploymentProgress;
  activePart: DronePartId | null;
  onSelect: (part: DronePartId) => void;
  onReady: () => void;
  fallback: ReactNode;
};

type ErrorBoundaryProps = { fallback: ReactNode; children: ReactNode };
type ErrorBoundaryState = { failed: boolean };

class SceneErrorBoundary extends React.Component<ErrorBoundaryProps, ErrorBoundaryState> {
  state: ErrorBoundaryState = { failed: false };

  static getDerivedStateFromError(): ErrorBoundaryState {
    return { failed: true };
  }

  render() {
    return this.state.failed ? this.props.fallback : this.props.children;
  }
}

function getQuality(): ParticleQuality {
  if (window.innerWidth <= 47 * 16) return 'mobile';
  if (window.innerWidth <= 63 * 16) return 'tablet';
  return 'desktop';
}

function supportsWebGL() {
  try {
    const canvas = document.createElement('canvas');
    return Boolean(canvas.getContext('webgl2') || canvas.getContext('webgl'));
  } catch {
    return false;
  }
}

export function DroneExperience({ progress, activePart, onSelect, onReady, fallback }: DroneExperienceProps) {
  const hostRef = useRef<HTMLDivElement>(null);
  const assemblyRef = useRef<DroneAssemblyHandle | null>(null);
  const [quality, setQuality] = useState<ParticleQuality>(() => getQuality());
  const [webgl] = useState<boolean>(() => supportsWebGL());
  const [inView, setInView] = useState(true);

  useEffect(() => {
    const updateQuality = () => setQuality(getQuality());
    window.addEventListener('resize', updateQuality, { passive: true });
    return () => window.removeEventListener('resize', updateQuality);
  }, []);

  useEffect(() => {
    const host = hostRef.current;
    if (!host) return;
    const observer = new IntersectionObserver(([entry]) => setInView(Boolean(entry?.isIntersecting)), { rootMargin: '120px' });
    observer.observe(host);
    return () => observer.disconnect();
  }, []);

  if (!webgl) return <>{fallback}</>;

  const dpr: ComponentProps<typeof Canvas>['dpr'] = quality === 'desktop' ? [1, 1.5] : [1, 1.25];

  return (
    <div ref={hostRef} className="drone-canvas-frame" aria-hidden="true">
      <SceneErrorBoundary fallback={fallback}>
        <Canvas
          camera={{ position: [0, 0.1, 5], fov: 38, near: 0.1, far: 30 }}
          dpr={dpr}
          frameloop={inView ? 'always' : 'never'}
          gl={{ antialias: true, alpha: true, powerPreference: 'high-performance' }}
          onCreated={({ gl }) => {
            gl.setClearColor('#050505', 0);
            onReady();
          }}
        >
          <ambientLight intensity={0.5} color="#d7d9dc" />
          <pointLight position={[1.6, 2.2, 3]} intensity={12} distance={8} color="#8b5cf6" />
          <directionalLight position={[-3, 2, 2]} intensity={1.8} color="#dfe3e8" />
          <SceneController
            progress={progress}
            assemblyRef={assemblyRef}
            desktop={quality === 'desktop'}
            sceneScale={quality === 'desktop' ? 1 : quality === 'tablet' ? 0.76 : 0.68}
          >
            <MeshParticleField progress={progress} quality={quality} />
            <DroneAssembly ref={assemblyRef} activePart={activePart} />
            <group position={[0, 0.28, 0.28]}>
              <ParticleIntelligenceCore progress={progress} quality={quality} desktop={quality === 'desktop'} />
            </group>
            <DroneHotspots progress={progress} activePart={activePart} onSelect={onSelect} />
          </SceneController>
        </Canvas>
      </SceneErrorBoundary>
    </div>
  );
}

import React from 'react';
