'use client';

import { useFrame, type ThreeEvent } from '@react-three/fiber';
import { useEffect, useLayoutEffect, useMemo, useRef } from 'react';
import * as THREE from 'three';
import type { DeploymentProgress } from './types';

type ParticleQuality = 'desktop' | 'tablet' | 'mobile';

const CORE_COUNTS: Record<ParticleQuality, number> = {
  desktop: 760,
  tablet: 620,
  mobile: 220,
};

type CoreData = {
  base: Float32Array;
  deployed: Float32Array;
  scatter: Float32Array;
  colors: Float32Array;
};

function buildCoreData(count: number): CoreData {
  const base = new Float32Array(count * 3);
  const deployed = new Float32Array(count * 3);
  const scatter = new Float32Array(count * 3);
  const colors = new Float32Array(count * 3);
  const violet = new THREE.Color('#8b5cf6');
  const cyan = new THREE.Color('#06b6d4');
  const white = new THREE.Color('#e5e2e1');

  for (let index = 0; index < count; index += 1) {
    const phi = Math.acos(1 - (2 * (index + 0.5)) / count);
    const theta = Math.PI * (1 + Math.sqrt(5)) * index;
    const radius = 0.2 + (index % 9) * 0.006;
    const i3 = index * 3;
    const x = Math.sin(phi) * Math.cos(theta);
    const y = Math.cos(phi);
    const z = Math.sin(phi) * Math.sin(theta);
    base[i3] = x * radius;
    base[i3 + 1] = y * radius;
    base[i3 + 2] = z * radius;
    deployed[i3] = x * (radius + 0.06 + (index % 4) * 0.012);
    deployed[i3 + 1] = y * (radius + 0.06 + (index % 5) * 0.01) + (index % 3 === 0 ? 0.02 : -0.01);
    scatter[i3] = x * (0.15 + (index % 7) * 0.01);
    scatter[i3 + 1] = y * (0.15 + (index % 5) * 0.01);
    scatter[i3 + 2] = z * (0.15 + (index % 6) * 0.01);
    const color = index % 5 === 0 ? cyan : index % 3 === 0 ? violet : white;
    colors[i3] = color.r;
    colors[i3 + 1] = color.g;
    colors[i3 + 2] = color.b;
  }

  return { base, deployed, scatter, colors };
}

export function ParticleIntelligenceCore({ progress, quality, desktop }: {
  progress: DeploymentProgress;
  quality: ParticleQuality;
  desktop: boolean;
}) {
  const pointsRef = useRef<THREE.Points>(null);
  const geometry = useMemo(() => new THREE.BufferGeometry(), []);
  const data = useMemo(() => buildCoreData(CORE_COUNTS[quality]), [quality]);
  const positions = useMemo(() => new Float32Array(data.base), [data]);
  const scatterRef = useRef(0);
  const pointerRef = useRef({ x: 0, y: 0 });
  const previousProgress = useRef(-1);

  useLayoutEffect(() => {
    geometry.setAttribute('position', new THREE.BufferAttribute(positions, 3));
    geometry.setAttribute('color', new THREE.BufferAttribute(data.colors, 3));
    geometry.computeBoundingSphere();
  }, [data.colors, geometry, positions]);

  useEffect(() => () => geometry.dispose(), [geometry]);

  useFrame((_, delta) => {
    const points = pointsRef.current;
    if (!points) return;
    const nextProgress = Math.max(0, Math.min(1, progress.value));
    const deltaProgress = Math.abs(nextProgress - previousProgress.current);
    scatterRef.current = Math.max(0, scatterRef.current - delta * 1.8);
    const needsPositionUpdate = deltaProgress > 0.0005 || scatterRef.current > 0.001;

    points.rotation.y += delta * 0.045;
    points.rotation.x = THREE.MathUtils.lerp(points.rotation.x, pointerRef.current.y * 0.08, 0.05);
    points.position.x = THREE.MathUtils.lerp(points.position.x, pointerRef.current.x * 0.06, 0.05);
    if (needsPositionUpdate) {
      const awaken = THREE.MathUtils.smoothstep(nextProgress, 0.1, 0.3);
      const attribute = geometry.getAttribute('position') as THREE.BufferAttribute;
      for (let index = 0; index < CORE_COUNTS[quality]; index += 1) {
        const i3 = index * 3;
        attribute.array[i3] = THREE.MathUtils.lerp(data.base[i3]!, data.deployed[i3]!, awaken) + data.scatter[i3]! * scatterRef.current;
        attribute.array[i3 + 1] = THREE.MathUtils.lerp(data.base[i3 + 1]!, data.deployed[i3 + 1]!, awaken) + data.scatter[i3 + 1]! * scatterRef.current;
        attribute.array[i3 + 2] = THREE.MathUtils.lerp(data.base[i3 + 2]!, data.deployed[i3 + 2]!, awaken) + data.scatter[i3 + 2]! * scatterRef.current;
      }
      attribute.needsUpdate = true;
      previousProgress.current = nextProgress;
    }
    const material = points.material as THREE.PointsMaterial;
    material.opacity = 0.38 + awakenOpacity(nextProgress) * 0.56;
    material.size = 0.025 + awakenOpacity(nextProgress) * 0.012;
  });

  const handlePointerMove = (event: ThreeEvent<PointerEvent>) => {
    if (!desktop) return;
    pointerRef.current.x = event.pointer.x;
    pointerRef.current.y = event.pointer.y;
  };

  const handlePointerDown = (event: ThreeEvent<PointerEvent>) => {
    if (!desktop) return;
    event.stopPropagation();
    scatterRef.current = 1;
  };

  return (
    <points
      ref={pointsRef}
      geometry={geometry}
      onPointerMove={handlePointerMove}
      onPointerDown={handlePointerDown}
      frustumCulled={false}
    >
      <pointsMaterial vertexColors transparent opacity={0.38} size={0.025} sizeAttenuation depthWrite={false} />
    </points>
  );
}

function awakenOpacity(progress: number) {
  return THREE.MathUtils.smoothstep(progress, 0.08, 0.28);
}

export type { ParticleQuality };
